        nx, ny = sx + dx, sy + dy
        if is_evader:
            # maximize distance from pursuer; keep toward a chosen corner by small bias
            d = md(nx, ny, ox, oy)
            cb = -md(nx, ny, target[0], target[1])
            center_pen = abs(nx - cx) + abs(ny - cy)
            return (d, cb, -center_pen)  # lexicographic maximize
